fn after_findings(&mut self, remaining: Vec<ReviewFinding>, yolo: bool, fix_ledger: &str) {
    if remaining.is_empty() {
        self.next = if self.stage { LoopNext::Stage } else { LoopNext::Done };
        return;
    }
    if self.iterations >= self.effective_cap(yolo) {
        if yolo {
            // YOLO resolution repeats while it converges (review-cap.js).
            let converging = match self.open_before_resolve {
                None => true,
                Some(before) => remaining.len() < before,
            };
            self.next = if self.resolve_rounds == 0 || converging {
                LoopNext::Resolve { findings: remaining }
            } else {
                LoopNext::Blocked { reason: format!("The review loop stopped converging after {} resolution rounds; {} findings remain open. Ledger: {fix_ledger}", self.resolve_rounds, remaining.len()) }
            };
        } else {
            self.next = LoopNext::CapReached { findings: remaining };
        }
        return;
    }
    self.next = LoopNext::Work {
        kind: WorkKind::Fix,
        instructions: Some(fix_instructions(&remaining, fix_ledger)),
    };
}

LoopNext::CapReached { findings } => {
    if s.yolo {
        // YOLO toggled on while the loop waited at its cap.
        self.push(Step::Judge {
            judge: JudgeKind::ResolveReview,
            subject: Some(loop_key_str((phase, tests))),
        });
    } else {
        self.gate(
            format!("Review of phase {phase} reached its cap"),
            format!(
                "{} review passes ran and {} findings are still open. Choose another fix-and-review pass, or stop and leave the phase blocked.",
                l.iterations,
                findings.len()
            ),
            GatePayload::ReviewCap {
                project,
                phase,
                tests,
                iterations: l.iterations,
                findings: findings.clone(),
                ledger_path: s.ledger_path(&p.info.project, phase, tests),
            },
        );
    }
}

fn plan_ctx(&self, st: &SessionState) -> PlanCtx {
    let mut ctx = PlanCtx::default();
    let budget = self.services.workspace().limits.session_budget_usd;
    ctx.budget_usd = (budget > 0.0).then_some(budget);
    for p in &st.projects {
        let profile: ProjectProfile =
            load_toml(&paths::project_profile(&p.path)).unwrap_or_default();
        ctx.format_commands.insert(
            p.key.clone(),
            profile.commands.format.filter(|c| !c.trim().is_empty()),
        );
    }
    ctx
}

