async fn acquire_slot(self: &Arc<Self>) -> Slot {
    loop {
        let limit = self
            .services
            .workspace()
            .limits
            .max_parallel_executions
            .max(1) as usize;
        {
            let mut n = lock(&self.slots);
            if *n < limit {
                *n += 1;
                return Slot(self.clone());
            }
        }
        let _ = tokio::time::timeout(std::time::Duration::from_secs(2), self.slot_free.notified()).await;
    }
}

